    protected override void OnClosed(EventArgs e)
    {
        clockTimer?.Stop();
        mediaTimer?.Stop();
        workTimer?.Stop();
        layoutSnapTimer.Stop();
        collapsedMusicMarqueeTimer?.Stop();
        lyricsLoadCancellation?.Cancel();
        lyricsLoadCancellation?.Dispose();
        artworkLoadCancellation?.Cancel();
        artworkLoadCancellation?.Dispose();
        AttachMediaSession(null);
        lyricsWatcher?.Dispose();
        lyricsWatcher=null;
        if(mediaManager!=null)
        {
            mediaManager.SessionsChanged-=MediaManager_Changed;
            mediaManager.CurrentSessionChanged-=MediaManager_Changed;
        }
        if(hwndSource!=null)
        {
            hwndSource.RemoveHook(ResizeHitTestHook);
            hwndSource=null;
        }
        base.OnClosed(e);
    }
    void ApplySkin() {
        if(PresentationSource.FromVisual(this)!=null)AcrylicHelper.Apply(this,model.Skin=="Acrylic",model.Opacity,model.Skin=="Dark");
        Opacity=1;model.Opacity=service.State.WidgetOpacity;var surfaceAlpha=(byte)Math.Clamp(model.Opacity*255,0,255);var headerAlpha=(byte)Math.Clamp(model.Opacity*255,0,255);
        var dark=model.Skin=="Dark";
        var honey=model.Skin=="Honey";
        var surfaceColor=dark?Color.FromArgb(surfaceAlpha,13,19,33):honey?Color.FromArgb(surfaceAlpha,255,244,222):Color.FromArgb(surfaceAlpha,245,247,250);
        var cappedHeaderAlpha=(byte)Math.Min(235,(int)headerAlpha);
        var headerColor=dark?Color.FromArgb(cappedHeaderAlpha,16,22,35):honey?Color.FromArgb(cappedHeaderAlpha,255,244,222):Color.FromArgb(cappedHeaderAlpha,245,247,250);
        RootBorder.Background=new SolidColorBrush(surfaceColor);
        HeaderBorder.Background=new SolidColorBrush(headerColor);
        RootBorder.BorderBrush=new SolidColorBrush(Color.FromArgb(dark?(byte)82:(byte)72,255,138,0));
        Foreground=dark?Brushes.White:new SolidColorBrush(Color.FromRgb(13,19,33));TitleBox.Foreground=Foreground;ClockTime.Foreground=Foreground;
        var backgroundPath=service.State.UseSharedWidgetBackground?service.State.SharedWidgetBackgroundPath:model.BackgroundImagePath;if(!string.IsNullOrWhiteSpace(backgroundPath)&&File.Exists(backgroundPath)){var image=LoadImage(backgroundPath);if(image!=null){RootBorder.Background=new ImageBrush(image){Stretch=Stretch.UniformToFill,AlignmentX=AlignmentX.Center,AlignmentY=AlignmentY.Center,Opacity=model.Opacity};ContentHost.Background=Brushes.Transparent;Foreground=ContrastHelper.TextFor(image,Foreground);}}else ContentHost.Background=Brushes.Transparent;
        if(model.Kind==NestKind.Music){Foreground=Brushes.White;TitleBox.Foreground=Brushes.White;HeaderBorder.Background=new SolidColorBrush(Color.FromArgb(105,5,9,16));}
        WeatherCity.Foreground=Foreground;WeatherTemp.Foreground=Foreground;WeatherDetail.Foreground=Foreground.Clone();WeatherDetail.Opacity=.78;
        if(model.Kind==NestKind.Weather)WeatherPanel.Background=Brushes.Transparent;
        ApplyUnifiedWidgetSurface();RefreshHeaderButtonColors();RefreshHeaderIcons();UpdateCollapsedWidgetHeader();ApplyTypography();if(model.Kind is NestKind.Folder or NestKind.ManagedFiles)RefreshFiles();if(model.Kind==NestKind.Capture&&IsInitialized)RefreshCaptures();
    }
    void RefreshHeaderIcons()
    {
        var fg=Foreground as System.Windows.Media.Brush;
        if(CollapseButton!=null)CollapseButton.Content=new WpfImage{Source=SvgIcon.Load("chevron-up",20,fg),Width=20,Height=20};
        if(SettingsBtn!=null)SettingsBtn.Content=new WpfImage{Source=SvgIcon.Load("settings",20,fg),Width=20,Height=20};
        if(HideBtn!=null)HideBtn.Content=new WpfImage{Source=SvgIcon.Load("minus",20,fg),Width=20,Height=20};
        if(HeaderBorder.Child is Grid header){var actions=header.Children.OfType<StackPanel>().FirstOrDefault(x=>Grid.GetColumn(x)==2);if(actions!=null)foreach(var b in actions.Children.OfType<Button>()){if(b.Tag?.ToString()=="pin")b.Content=new WpfImage{Source=SvgIcon.Load("pin",16,fg),Width=16,Height=16};if(b.Tag?.ToString()=="lock")b.Content=new WpfImage{Source=SvgIcon.Load(model.Locked?"lock":"lock-open",16,fg),Width=16,Height=16};}}
    }
    void ApplyUnifiedWidgetSurface()
    {
        var dark=model.Skin=="Dark";
        var input=new SolidColorBrush(Color.FromArgb(dark?(byte)64:(byte)165,255,255,255));
        foreach(var list in new System.Windows.Controls.Control[]{TodoList,FileList,CaptureList,AlarmList}){if(string.IsNullOrWhiteSpace(model.TextBackgroundColor))list.Background=Brushes.Transparent;list.BorderThickness=new Thickness(0);}
        foreach(var box in new[]{TodoInput,captureSearch}.Where(x=>x!=null).Cast<TextBox>()){box.Background=input;box.BorderBrush=new SolidColorBrush(Color.FromArgb(dark?(byte)82:(byte)110,255,255,255));box.Foreground=Foreground;box.CaretBrush=Foreground;}
        // WeatherCity 是只读城市显示，不应有输入框外观，保持透明无框
        WeatherCity.Background=Brushes.Transparent;WeatherCity.BorderThickness=new Thickness(0);WeatherCity.Foreground=Foreground;WeatherCity.CaretBrush=Foreground;
        foreach(var panel in new[]{TodoPanel,FolderPanel,CapturePanel,ClockPanel,WeatherPanel,MusicPanel})panel.Background=Brushes.Transparent;
        if(model.Kind==NestKind.Capture){var tabs=new[]{CaptureAllTab,CaptureClipboardTab,CaptureManualTab};foreach(var button in CapturePanel.Children.OfType<Grid>().SelectMany(g=>g.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>()).SelectMany(g=>g.Children.OfType<Button>())){if(tabs.Contains(button))continue;button.Background=new SolidColorBrush(Color.FromRgb(255,243,229));button.Foreground=new SolidColorBrush(Color.FromRgb(13,19,33));}}
    }
