    void SnapToGrid(){if(snapping||!service.State.AlignWidgetsToGrid)return;snapping=true;try{var grid=Math.Clamp(service.State.WidgetGridSize,10,80);var sense=Math.Max(8,Math.Min(24,grid*.7));var gap=Math.Max(8,Math.Min(20,grid*.45));double left=Math.Round(Left/grid)*grid,top=Math.Round(Top/grid)*grid,width=Math.Max(MinWidth,Math.Round(ActualWidth/grid)*grid),height=Math.Max(MinHeight,Math.Round(ActualHeight/grid)*grid);var work=SystemParameters.WorkArea;SnapEdge(ref left,work.Left,sense);SnapEdge(ref top,work.Top,sense);if(Math.Abs(left+width-work.Right)<=sense)left=work.Right-width;if(Math.Abs(top+height-work.Bottom)<=sense)top=work.Bottom-height;var others=service.GetWidgetBounds(model.Id).ToList();foreach(var other in others){if(Math.Abs(left-(other.Right+gap))<=sense)left=other.Right+gap;if(Math.Abs(left+width-(other.Left-gap))<=sense)left=other.Left-gap-width;if(Math.Abs(top-(other.Bottom+gap))<=sense)top=other.Bottom+gap;if(Math.Abs(top+height-(other.Top-gap))<=sense)top=other.Top-gap-height;}for(var pass=0;pass<4;pass++){var moved=false;foreach(var other in others){var expanded=new Rect(other.Left-gap,other.Top-gap,other.Width+gap*2,other.Height+gap*2);var current=new Rect(left,top,width,height);if(!current.IntersectsWith(expanded))continue;var right=expanded.Right-left;var leftMove=left+width-expanded.Left;var down=expanded.Bottom-top;var up=top+height-expanded.Top;var candidates=new List<(double Value,Action Move)>{(right,()=>left=expanded.Right),(leftMove,()=>left=expanded.Left-width),(down,()=>top=expanded.Bottom),(up,()=>top=expanded.Top-height)}.Where(x=>x.Value>0).OrderBy(x=>x.Value).ToList();if(candidates.Count==0)continue;candidates[0].Move();moved=true;left=Math.Clamp(left,work.Left,Math.Max(work.Left,work.Right-width));top=Math.Clamp(top,work.Top,Math.Max(work.Top,work.Bottom-height));}if(!moved)break;}left=Math.Clamp(left,work.Left,Math.Max(work.Left,work.Right-width));top=Math.Clamp(top,work.Top,Math.Max(work.Top,work.Bottom-height));Left=left;