    static double InputHeight(double fontSize)=>Math.Ceiling(Math.Max(36,fontSize*2.4+8));
    static Thickness InputPadding(double fontSize)=>new(10,Math.Max(4,fontSize*.25),10,Math.Max(4,fontSize*.25));
    void UpdateInputMetrics()
    {
        var uiFont=ResponsiveUiFont();
        var inputHeight=InputHeight(uiFont);
        TodoInput.FontSize=uiFont;TodoInput.MinHeight=inputHeight;TodoInput.Height=inputHeight;TodoInput.Padding=InputPadding(uiFont);
        if(TodoInput.Parent is Grid row)foreach(var button in row.Children.OfType<Button>()){button.MinHeight=inputHeight;button.Height=inputHeight;button.Width=Math.Max(46,inputHeight);}
        var buttonHeight=Math.Ceiling(Math.Max(32,uiFont*1.25+13));
        foreach(var button in CapturePanel.Children.OfType<Grid>().SelectMany(g=>g.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>()).SelectMany(g=>g.Children.OfType<Button>()))
        {
            button.MinHeight=buttonHeight;
            button.Height=buttonHeight;
            button.FontSize=uiFont;
            button.Padding=new Thickness(3,1,3,1);
        }
        CaptureList.FontSize=uiFont;FileList.FontSize=uiFont;TodoList.FontSize=uiFont;
        if(captureSearch!=null){captureSearch.FontSize=uiFont;captureSearch.MinHeight=inputHeight;captureSearch.MaxHeight=inputHeight+2;captureSearch.Padding=InputPadding(uiFont);}
        WeatherCity.FontSize=Math.Max(11,Math.Min(ResponsiveUiFont(),16));WeatherCity.MinHeight=0;WeatherCity.Padding=new Thickness(4);
        TitleBox.MinHeight=Math.Ceiling(Math.Max(34,TitleBox.FontSize*1.45+10));TitleBox.Padding=new Thickness(5,2,5,2);
        if(tagsInput!=null){tagsInput.MinHeight=inputHeight;tagsInput.Padding=InputPadding(model.FontSize);}
    }
