    void BuildDatePanels(){deadlinePanel=new Grid{Visibility=Visibility.Collapsed};deadlinePanel.RowDefinitions.Add(new RowDefinition());deadlinePanel.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});deadlineList=new ListBox{BorderThickness=new Thickness(0),Background=Brushes.Transparent};var deadlineSelector=new DeadlineTemplateSelector{HeaderTemplate=BuildDeadlineHeaderTemplate(),ItemTemplate=BuildDeadlineItemTemplate()};deadlineList.ItemTemplateSelector=deadlineSelector;var deadlineMenu=new ContextMenu();var doneItem=new MenuItem{Header=Localization.T("標記完成",service.State.Language)};doneItem.Click+=(_,_)=>{if(deadlineList.SelectedItem is DeadlineRow{Item:not null} row){row.Item.Done=true;service.Save();RefreshDatePanels();RefreshTodos();}};var postponeItem=new MenuItem{Header=Localization.T("延後 1 天",service.State.Language)};postponeItem.Click+=(_,_)=>{if(deadlineList.SelectedItem is DeadlineRow{Item:not null} row){row.Item.DueAt=(row.Item.DueAt??DateTime.Now).AddDays(1);row.Item.ReminderDismissed=false;row.Item.SentReminderOffsets.Clear();service.Save();RefreshDatePanels();RefreshTodos();}};var locateItem=new MenuItem{Header=Localization.T("定位到待辦格子",service.State.Language)};locateItem.Click+=(_,_)=>{if(deadlineList.SelectedItem is DeadlineRow{Item:not null} row){var nest=service.State.Nests.FirstOrDefault(n=>n.Kind==NestKind.Todo&&n.Todos.Contains(row.Item));if(nest!=null)service.SetVisible(nest,true);}};deadlineMenu.Items.Add(doneItem);deadlineMenu.Items.Add(postponeItem);deadlineMenu.Items.Add(locateItem);StyleContextMenu(deadlineMenu);deadlineList.ContextMenu=deadlineMenu;deadlinePanel.Children.Add(deadlineList);var hint=new TextBlock{Text=Localization.T("雙擊項目可修改待辦詳情與 Deadline",service.State.Language),Foreground=Brushes.Gray,Margin=new Thickness(4,8,4,2)};Grid.SetRow(hint,1);deadlinePanel.Children.Add(hint);ContentHost.Children.Add(deadlinePanel);countdownPanel=new Grid{Visibility=Visibility.Collapsed};countdownPanel.RowDefinitions.Add(new RowDefi