    void StartDateRefresh(){RefreshDatePanels();clockTimer=new DispatcherTimer{Interval=TimeSpan.FromMinutes(1)};clockTimer.Tick+=(_,_)=>RefreshDatePanels();clockTimer.Start();}
    void RefreshDatePanels(){var lang=service.State.Language;if(deadlineList!=null){var items=service.State.Nests.Where(n=>n.Kind==NestKind.Todo).SelectMany(n=>n.Todos).Where(t=>!t.Done&&t.DueAt.HasValue).OrderBy(t=>t.DueAt).ToList();var rows=new List<DeadlineRow>();string? lastGroup=null;var overdueBrush=new SolidColorBrush(Color.FromRgb(217,45,32));var todayBrush=new SolidColorBrush(Color.FromRgb(247,144,9));var normalBrush=model.Skin=="Dark"?Brushes.White:new SolidColorBrush(Color.FromRgb(13,19,33));foreach(var t in items){var due=t.DueAt!.Value;var group=due<DateTime.Now?Localization.T("逾期",lang):due.Date==DateTime.Today?Localization.T("今天",lang):due.Date<=DateTime.Today.AddDays(7)?Localization.T("7 天內",lang):Localization.T("更晚",lang);var accent=due<DateTime.Now?overdueBrush:due.Date==DateTime.Today?todayBrush:normalBrush;if(group!=lastGroup){rows.Add(new DeadlineRow(null,group,accent,true));lastGroup=group;}rows.Add(new DeadlineRow(t,$"{t.Text}\n{due:yyyy/MM/dd HH:mm}  ·  {DeadlineCountdownText(t,lang)}",accent,false));}deadlineList.ItemsSource=rows;}if(countdownList!=null)countdownList.ItemsSource=model.Countdowns.OrderBy(x=>CountdownTarget(x)).Select(x=>{var target=CountdownTarget(x);var days=(target.Date-DateTime.Today).Days;var status=days==0?Localization.T("就是今天",lang):days>0?Localization.Format("還有 {0} 天",lang,days):Localization.Format("已過 {0} 天",lang,-days);Brush color;try{color=(Brush)new BrushConverter().ConvertFromString(string.IsNullOrWhiteSpace(x.FontColor)?model.FontColor:x.FontColor)!;}catch{color=Foreground;}return new CountdownRow(x,x.Title,$"{target:yyyy/MM/dd}  ·  {status}{(x.Annual?"  ·  "+Localization.T("每年",lang):"")}",string.IsNullOrWhiteSpace(x.FontFamily)?model.FontFamily:x.FontFamily,x.FontSize<=0?model.FontSize:x.FontSize,color);}).ToList();}
    static string DeadlineCountdownText(TodoItem t,string lang){if(!t.DueAt.HasValue)return "";var span=t.DueAt.Value-DateTime.Now;if(span<=TimeSpan.Zero){var overdue=-span;return overdue.TotalDays>=1?Localization.Format("已逾期 {0} 天",lang,(int)overdue.TotalDays):Localization.Format("已逾期 {0} 小時",lang,Math.Max(1,(int)overdue.TotalHours));}if(span.TotalDays>=1)return Localization.Format("剩餘 {0} 天 {1} 小時",lang,(int)span.TotalDays,span.Hours);if(span.TotalHours>=1)return Localization.Format("剩餘 {0} 小時 {1} 分",lang,(int)span.TotalHours,span.Minutes);return Localization.Format("剩餘 {0} 分鐘",lang,Math.Max(1,span.Minutes));}
    static DateTime CountdownTarget(CountdownItem item){if(!item.Annual)return item.Date;var year=DateTime.Today.Year;var day=Math.Min(item.Date.Day,DateTime.DaysInMonth(year,item.Date.Month));var target=new DateTime(year,item.Date.Month,day);if(target.Date<DateTime.Today){year++;day=Math.Min(item.Date.Day,DateTime.DaysInMonth(year,item.Date.Month));target=new DateTime(year,item.Date.Month,day);}return target;}
    void EditCountdown(CountdownItem? item){var editing=item??new CountdownItem{FontFamily=model.FontFamily,FontSize=model.FontSize,FontColor=model.FontColor};if(!BeeXCountdownDialog.TryEdit(this,service.State,editing,out var title,out var date,out var annual,out var fontFamily,out var fontSize,out var fontColor))return;editing.Title=title;editing.Date=date;editing.Annual=annual;editing.FontFamily=fontFamily;editing.FontSize=fontSize;editing.FontColor=fontColor;if(item==null)model.Countdowns.Add(editing);service.Save();RefreshDatePanels();}
    static DataTemplate BuildCountdownTemplate(){var template=new DataTemplate(typeof(CountdownRow));var panel=new FrameworkElementFactory(typeof(StackPanel));panel.SetValue(StackPanel.MarginProperty,new Thickness(6,7,6,7));var title=new FrameworkElementFactory(typeof(TextBlock));title.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Title"));title.SetBinding(TextBlock.FontFamilyProperty,new System.Windows.Data.Binding("FontFamily"));title.SetBinding(TextBlock.FontSizeProperty,new System.Windows.Data.Binding("FontSize"));title.SetBinding(TextBlock.ForegroundProperty,new System.Windows.Data.Binding("Foreground"));title.SetValue(TextBlock.FontWeightProperty,FontWeights.SemiBold);var detail=new FrameworkElementFactory(typeof(TextBlock));detail.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Detail"));detail.SetBinding(TextBlock.FontFamilyProperty,new System.Windows.Data.Binding("FontFamily"));detail.SetBinding(TextBlock.FontSizeProperty,new System.Windows.Data.Binding("FontSize"));detail.SetBinding(TextBlock.ForegroundProperty,new System.Windows.Data.Binding("Foreground"));detail.SetValue(TextBlock.OpacityProperty,.78);panel.AppendChild(title);panel.AppendChild(detail);template.VisualTree=panel;return template;}
    TextBlock AddMonitorCard(Panel parent,string title,string initial,System.Windows.Media.Brush accent,out System.Windows.Controls.ProgressBar bar){var card=new Border{CornerRadius=new CornerRadius(10),Background=new SolidColorBrush(Color.FromArgb(42,255,138,0)),Margin=new Thickness(0,3,0,3),Padding=new Thickness(8,6,8,6)};var stack=new StackPanel();var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{MinWidth=0});grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.Children.Add(new TextBlock{Text=title,VerticalAlignment=VerticalAlignment.Center,TextTrimming=TextTrimming.CharacterEllipsis,FontSize=Math.Max(11,service.ContentFontSize()-1)});var value=new TextBlock{Text=initial,FontWeight=FontWeights.SemiBold,Foreground=accent,Margin=new Thickness(5,0,0,0),FontSize=Math.Max(10,service.ContentFontSize()-2),TextAlignment=TextAlignment.Right,TextTrimming=TextTrimming.CharacterEllipsis};Grid.SetColumn(value,1);grid.Children.Add(value);stack.Children.Add(grid);bar=new System.Windows.Controls.ProgressBar{Minimum=0,Maximum=100,Height=5,Margin=new Thickness(0,5,0,1),Foreground=accent,Background=new SolidColorBrush(Color.FromArgb(30,128,128,128)),BorderThickness=new Thickness(0),Value=0};stack.Children.Add(bar);card.Child=stack;parent.Children.Add(card);return value;}
