    void RenameTag(TagItem item){var d=new Window{Title=Localization.T("重新命名",service.State.Language),Width=420,Height=160,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(18)};var box=new TextBox{Text=item.Name,MinHeight=InputHeight(model.FontSize),Padding=InputPadding(model.FontSize)};var ok=new Button{Content=Localization.T("確定",service.State.Language),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};ok.Click+=(_,_)=>{var name=box.Text.Trim();if(name.Length==0)return;item.Name=name;service.Save();RefreshTags();d.Close();};box.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){ok.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));e.Handled=true;}};p.Children.Add(box);p.Children.Add(ok);d.Content=p;d.ShowDialog();}
    static DataTemplate BuildTagTemplate(){var template=new DataTemplate(typeof(TagRow));var panel=new FrameworkElementFactory(typeof(StackPanel));panel.SetValue(StackPanel.MarginProperty,new Thickness(4,5,4,5));var name=new FrameworkElementFactory(typeof(TextBlock));name.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Name"));name.SetValue(TextBlock.FontWeightProperty,FontWeights.SemiBold);var time=new FrameworkElementFactory(typeof(TextBlock));time.SetBinding(TextBlock.TextProperty,new System.Windows.Data.Binding("Time"));time.SetValue(TextBlock.FontSizeProperty,10d);time.SetValue(TextBlock.ForegroundProperty,Brushes.Gray);panel.AppendChild(name);panel.AppendChild(time);template.VisualTree=panel;return template;}
    static long TotalNetworkBytes()=>NetworkInterface.GetAllNetworkInterfaces().Where(n=>{try{return n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback;}catch{return false;}}).Sum(n=>{try{var s=n.GetIPv4Statistics();return s.BytesReceived+s.BytesSent;}catch{return 0L;}});
    void StartSystemMonitor(){systemCpuReady=false;ReadSystemCpuUsage();lastNetworkBytes=TotalNetworkBytes();lastNetworkAt=DateTime.UtcNow;void Update(){try{var cpu=ReadSystemCpuUsage();var (memory,used,total)=GetSystemMemoryUsage();var bytes=TotalNetworkBytes();var now=DateTime.UtcNow;var seconds=Math.Max(.2,(now-lastNetworkAt).TotalSeconds);var rate=Math.Max(0,bytes-lastNetworkBytes)/1024d/seconds;lastNetworkBytes=bytes;lastNetworkAt=now;if(cpuValue!=null)cpuValue.Text=$"{cpu:0}%";if(cpuBar!=null)cpuBar.Value=Math.Clamp(cpu,0,100);if(memoryValue!=null)memoryValue.Text=$"{memory:0}% · {FormatCompactBytes(used)}/{FormatCompactBytes(total)}";if(memoryBar!=null)memoryBar.Value=Math.Clamp(memory,0,100);if(networkValue!=null)networkValue.Text=rate>=1024?$"{rate/1024:0.0} MB/s":$"{rate:0} KB/s";if(networkBar!=null)networkBar.Value=Math.Clamp(rate/1024/10*100,0,100);}catch{if(cpuValue!=null)cpuValue.Text="--";if(memoryValue!=null)memoryValue.Text="--";if(networkValue!=null)networkValue.Text="--";}UpdateCollapsedWidgetHeader();}clockTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};clockTimer.Tick+=(_,_)=>Update();Update();clockTimer.Start();}
    double ReadSystemCpuUsage(){if(!GetSystemTimes(out var idle,out var kernel,out var user))return 0;var idleNow=idle.ToUInt64();var kernelNow=kernel.ToUInt64();var userNow=user.ToUInt64();if(!systemCpuReady){lastSystemIdle=idleNow;lastSystemKernel=kernelNow;lastSystemUser=userNow;systemCpuReady=true;return 0;}var idleDelta=idleNow-lastSystemIdle;var kernelDelta=kernelNow-lastSystemKernel;var userDelta=userNow-lastSystemUser;lastSystemIdle=idleNow;lastSystemKernel=kernelNow;lastSystemUser=userNow;var total=kernelDelta+userDelta;if(total==0)return 0;return Math.Clamp((1-idleDelta/(double)total)*100,0,100);}
    static (double Percent,ulong Used,ulong Total) GetSystemMemoryUsage(){var status=new MemoryStatusEx();if(!GlobalMemoryStatusEx(status)||status.ullTotalPhys==0)return (0,0,0);var used=status.ullTotalPhys-status.ullAvailPhys;return (used*100d/status.ullTotalPhys,used,status.ullTotalPhys);}
    static string FormatBytes(ulong bytes){double gb=bytes/1024d/1024d/1024d;if(gb>=10)return $"{gb:0} GB";if(gb>=1)return $"{gb:0.0} GB";return $"{bytes/1024d/1024d:0} MB";}
    static string FormatCompactBytes(ulong bytes){double gb=bytes/1024d/1024d/1024d;if(gb>=10)return $"{gb:0}G";if(gb>=1)return $"{gb:0.0}G";return $"{bytes/1024d/1024d:0}M";}
    [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)]
    sealed class MemoryStatusEx{public uint dwLength=(uint)Marshal.SizeOf<MemoryStatusEx>();public uint dwMemoryLoad;public ulong ullTotalPhys;public ulong ullAvailPhys;public ulong ullTotalPageFile;public ulong ullAvailPageFile;public ulong ullTotalVirtual;public ulong ullAvailVirtual;public ulong ullAvailExtendedVirtual;}
    [StructLayout(LayoutKind.Sequential)]
    struct FileTimeValue{public uint LowDateTime;public uint HighDateTime;public ulong ToUInt64()=>((ulong)HighDateTime<<32)|LowDateTime;}
    [DllImport("kernel32.dll",SetLastError=true)]
    static extern bool GlobalMemoryStatusEx([In,Out] MemoryStatusEx lpBuffer);
    [DllImport("kernel32.dll",SetLastError=true)]
    static extern bool GetSystemTimes(out FileTimeValue idleTime,out FileTimeValue kernelTime,out FileTimeValue userTime);
