    void RefreshTodos(){IEnumerable<TodoItem> items=model.Todos;var today=DateTime.Today;var todayCount=model.Todos.Count(x=>!x.Done&&x.DueAt?.Date==today);var importantCount=model.Todos.Count(x=>!x.Done&&(x.Color=="#D92D20"||x.Color=="#7F56D9"));var doneCount=model.Todos.Count(x=>x.Done);items=todoFilter switch{"Today"=>items.Where(x=>!x.Done&&x.DueAt?.Date==today),"Important"=>items.Where(x=>!x.Done&&(x.Color=="#D92D20"||x.Color=="#7F56D9")),"Done"=>items.Where(x=>x.Done),_=>items};if(!string.IsNullOrEmpty(todoColorFilter))items=items.Where(x=>x.Color.Equals(todoColorFilter,StringComparison.OrdinalIgnoreCase));TodoList.ItemsSource=items.ToList();if(!IsInitialized)return;var lang=service.State.Language;TodoAllTab.Content=$"{Localization.T("全部",lang)} {model.Todos.Count}";TodoTodayTab.Content=$"{Localization.T("今天",lang)} {todayCount}";TodoImportantTab.Content=$"{Localization.T("重要",lang)} {importantCount}";TodoDoneTab.Content=$"{Localization.T("已完成",lang)} {doneCount}";TodoRemaining.Text=Localization.Format("剩餘 {0} 項",lang,model.Todos.Count-doneCount);TodoAllTab.ToolTip=Localization.T("全部",lang);TodoTodayTab.ToolTip=Localization.T("今天",lang);TodoImportantTab.ToolTip=Localization.T("重要",lang);TodoDoneTab.ToolTip=Localization.T("已完成",lang);foreach(var b in new[]{TodoAllTab,TodoTodayTab,TodoImportantTab,TodoDoneTab}){var on=b.Tag?.ToString()==todoFilter;b.Background=on?new SolidColorBrush(Color.FromRgb(255,138,0)):new SolidColorBrush(Color.FromRgb(255,243,229));b.Foreground=on?Brushes.White:new SolidColorBrush(Color.FromRgb(13,19,33));}foreach(var b in ((StackPanel)TodoPanel.Children[2]).Children.OfType<Button>())b.BorderThickness=new Thickness(b.Tag?.ToString()==todoColorFilter?3:0);}
    void AddTodo_Click(object s,RoutedEventArgs e)=>AddTodo();
    void TodoInput_KeyDown(object s,System.Windows.Input.KeyEventArgs e){if(e.Key==Key.Enter){AddTodo();e.Handled=true;}}
    void AddTodo(){var text=TodoInput.Text.Trim();if(text.Length==0)return;model.Todos.Add(new TodoItem{Text=text,Color=selectedTodoColor,ReminderOffsets=[..service.State.TodoDefaultReminderOffsets]});TodoInput.Clear();RefreshTodos();service.Save();}
    void TodoFilter_Click(object s,RoutedEventArgs e){todoFilter=((FrameworkElement)s).Tag?.ToString()??"All";RefreshTodos();}
    void TodoColor_Click(object s,RoutedEventArgs e){var color=((FrameworkElement)s).Tag?.ToString()??"";if(Keyboard.Modifiers.HasFlag(ModifierKeys.Control)){todoColorFilter=todoColorFilter==color?"":color;RefreshTodos();return;}var selected=TodoList.SelectedItems.Cast<TodoItem>().ToList();selectedTodoColor=color;if(selected.Count==0){TodoInput.BorderBrush=(Brush)new BrushConverter().ConvertFromString(color)!;RefreshTodos();return;}foreach(var todo in selected)todo.Color=color;service.Save();RefreshTodos();foreach(var todo in selected)if(TodoList.Items.Contains(todo))TodoList.SelectedItems.Add(todo);}
    void ConfigureTodoColors(){if(TodoPanel.Children[2] is not StackPanel palette)return;var tip=Localization.T("點擊：套用到選中待辦；未選中時設為新任務顏色",service.State.Language)+"\nCtrl + "+Localization.T("點擊篩選",service.State.Language);foreach(var button in palette.Children.OfType<Button>())button.ToolTip=tip;}
    void ClearCompleted_Click(object s,RoutedEventArgs e){if(model.Todos.Count(x=>x.Done)==0)return;if(!BeeXDialog.Confirm(this,Localization.T("清除已完成待辦",service.State.Language),Localization.T("確定清除所有已完成待辦？",service.State.Language),service.State,Localization.T("清除",service.State.Language)))return;model.Todos.RemoveAll(x=>x.Done);RefreshTodos();service.Save();}
    void Todo_Changed(object s,RoutedEventArgs e){if(loading)return;if(s is System.Windows.Controls.CheckBox box&&box.DataContext is TodoItem todo)todo.Done=box.IsChecked==true;service.Save();}
    // 子項勾選聯動：全部子項完成→大項自動打勾；大項已勾但取消了某子項→大項自動取消（TodoItem 無 INPC，需延遲刷新列表同步 UI）
    void Subtodo_Changed(object s,RoutedEventArgs e){if(loading)return;if(s is System.Windows.Controls.CheckBox box&&box.DataContext is TodoSubItem sub){sub.Done=box.IsChecked==true;var parent=model.Todos.FirstOrDefault(t=>t.SubItems.Contains(sub));if(parent!=null&&parent.SubItems.Count>0){var all=parent.SubItems.All(x=>x.Done);if(all!=parent.Done){parent.Done=all;Dispatcher.BeginInvoke(new Action(RefreshTodos),DispatcherPriority.Background);}}}service.Save();}
    void SubExpandToggle_Click(object s,RoutedEventArgs e){if(s is FrameworkElement fe&&fe.DataContext is TodoItem t){t.SubExpanded=!t.SubExpanded;service.Save();RefreshTodos();}}
    System.Windows.Point todoDragStart;bool todoDragArmed;TodoItem? todoDragItem;
    void EnableTodoReorder(){TodoList.AllowDrop=true;TodoList.PreviewMouseLeftButtonDown+=(_,e)=>{todoDragArmed=false;todoDragItem=null;var c=VisualTreeUtils.FindParent<ListBoxItem>(e.OriginalSource as DependencyObject);if(c?.DataContext is TodoItem t){todoDragStart=e.GetPosition(TodoList);todoDragItem=t;todoDragArmed=true;}};TodoList.PreviewMouseMove+=(_,e)=>{if(!todoDragArmed||e.LeftButton!=MouseButtonState.Pressed||todoDragItem==null)return;var p=e.GetPosition(TodoList);if(Math.Abs(p.X-todoDragStart.X)<SystemParameters.MinimumHorizontalDragDistance&&Math.Abs(p.Y-todoDragStart.Y)<SystemParameters.MinimumVerticalDragDistance)return;var dragged=todoDragItem;todoDragArmed=false;todoDragItem=null;try{DragDrop.DoDragDrop(TodoList,dragged,DragDropEffects.Move);}catch{}};TodoList.Drop+=(_,e)=>{if(!e.Data.GetDataPresent(typeof(TodoItem)))return;var item=(TodoItem)e.Data.GetData(typeof(TodoItem));if(!model.Todos.Contains(item))return;var hit=TodoList.InputHitTest(e.GetPosition(TodoList)) as DependencyObject;while(hit!=null&&hit is not ListBoxItem)hit=VisualTreeHelper.GetParent(hit);var target=(hit as ListBoxItem)?.DataContext as TodoItem;if(target==item)return;model.Todos.Remove(item);var index=target!=null?model.Todos.IndexOf(target):model.Todos.Count;if(index<0)index=model.Todos.Count;model.Todos.Insert(Math.Clamp(index,0,model.Todos.Count),item);RefreshTodos();service.Save();};}
    void ConfigureTodo(){TodoList.MouseDoubleClick+=(_,e)=>{if(VisualTreeUtils.FindParent<System.Windows.Controls.CheckBox>(e.OriginalSource as DependencyObject)!=null)return;if(TodoList.SelectedItem is TodoItem t)OpenBeeXTodoDetail(t);};var menu=new ContextMenu();var done=new MenuItem{Header=Localization.T("標記完成",service.State.Language)};done.Click+=(_,_)=>{foreach(TodoItem t in TodoList.SelectedItems)t.Done=true;RefreshTodos();service.Save();menu.IsOpen=false;};var del=new MenuItem{Header=Localization.T("刪除",service.State.Language),Foreground=Brushes.Red};del.Click+=(_,_)=>{var selected=TodoList.SelectedItems.Cast<TodoItem>().ToList();menu.IsOpen=false;if(selected.Count==0||!BeeXDialog.Confirm(this,Localization.T("刪除待辦",service.State.Language),Localization.Format("確定刪除選中的 {0} 項待辦？",service.State.Language,selected.Count),service.State))return;foreach(var t in selected)model.Todos.Remove(t);RefreshTodos();service.Save();};menu.Opened+=(_,_)=>{done.Header=Localization.T("標記完成",service.State.Language);del.Header=Localization.T("刪除",service.State.Language);};menu.Items.Add(done);menu.Items.Add(del);StyleContextMenu(menu);TodoList.ContextMenu=menu;TodoList.SelectionMode=SelectionMode.Extended;}
    void OpenBeeXTodoDetail(TodoItem t){if(!BeeXTodoDialog.Edit(this,service.State,t))return;service.Save();RefreshTodos();RefreshDatePanels();}
    void AddTodoDetailButton(){if(TodoInput.Parent is not Grid row||row.Children.OfType<Button>().Any(x=>x.Tag?.ToString()=="detail-add"))return;var fg=Foreground as System.Windows.Media.Brush??System.Windows.Media.Brushes.Black;var dark=service.State.Theme=="Dark";
    // 需求1：＋ 用 plus 图标（橙底白色）
    if(AddTodoButton!=null)AddTodoButton.Content=new WpfImage{Source=SvgIcon.Load("plus",18,System.Windows.Media.Brushes.White),Width=18,Height=18};
    // 需求3：清除已完成 给可见的按钮底色（全局默认半透明奶油色在白底几乎看不见）
    if(ClearCompletedButton!=null){ClearCompletedButton.Background=dark?new SolidColorBrush(Color.FromArgb(46,255,255,255)):new SolidColorBrush(Color.FromRgb(255,235,214));ClearCompletedButton.Foreground=fg;ClearCompletedButton.Padding=new Thickness(12,6,12,6);ClearCompletedButton.FontSize=12;}
    row.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var button=new Button{Content=new WpfImage{Source=SvgIcon.Load("dots",18,fg),Width=18,Height=18},Tag="detail-add",ToolTip=Localization.T("詳細新增：時間、顏色、重複與附件",service.State.Language),Width=46,Height=42,Padding=new Thickness(0),Margin=new Thickness(4,0,0,0)};Grid.SetColumn(button,2);button.Click+=(_,_)=>{var item=new TodoItem{Text=TodoInput.Text.Trim(),DueAt=DateTime.Now.AddHours(1),Color=selectedTodoColor,ReminderOffsets=[..service.State.TodoDefaultReminderOffsets]};if(!BeeXTodoDialog.Edit(this,service.State,item))return;model.Todos.Add(item);TodoInput.Clear();service.Save();RefreshTodos();RefreshDatePanels();};row.Children.Add(button);}
    void StartTodoCountdown(){clockTimer=new DispatcherTimer{Interval=TimeSpan.FromMinutes(1)};clockTimer.Tick+=(_,_)=>RefreshTodos();clockTimer.Start();}
    /// <summary>天氣自動刷新：間隔由設定頁控制（0 分鐘表示關閉）</summary>
    void StartWeatherAutoRefresh(){var minutes=(int)Math.Clamp(service.State.WeatherRefreshMinutes,0,720);if(minutes<=0)return;clockTimer=new DispatcherTimer{Interval=TimeSpan.FromMinutes(minutes)};clockTimer.Tick+=async(_,_)=>{try{await LoadWeatherAsync(true);}catch{}};clockTimer.Start();}
    void RefreshFiles(){try{var s=service.State;var primary=Foreground;var secondary=primary.CloneCurrentValue();secondary.Opacity=Math.Min(secondary.Opacity,.74);if(secondary.CanFreeze)secondary.Freeze();FileList.ItemsSource=Directory.EnumerateFileSystemEntries(model.FolderPath).Take(fileVisibleLimit).Select(p=>new FileRow(p,Directory.Exists(p)||s.ShowFileExtensions?Path.GetFileName(p):Path.GetFileNameWithoutExtension(p),Directory.Exists(p)?"📁":"▧",Directory.Exists(p)?Localization.T("資料夾",s.Language):new FileInfo(p).LastWriteTime.ToString("yyyy/MM/dd HH:mm"),s.IconSize,new Thickness(3,s.ItemSpacing/2,3,s.ItemSpacing/2),primary,secondary)).ToList();}catch{FileList.ItemsSource=null;}}
    void ConfigureFiles(){FileList.SelectionMode=SelectionMode.Extended;FileList.KeyDown+=FileList_KeyDown;FileList.AddHandler(ScrollViewer.ScrollChangedEvent,new ScrollChangedEventHandler(FileList_ScrollChanged));var menu=new ContextMenu();void Add(string title,Action action){var i=new MenuItem{Header=title};i.Click+=(_,_)=>{menu.IsOpen=false;action();};menu.Items.Add(i);}Add("打開",()=>OpenSelected());Add("在檔案總管中顯示",()=>RevealSelected());Add("複製",()=>CopySelected(false));Add("剪切",()=>CopySelected(true));Add("粘貼",PasteFiles);Add("重新命名",RenameSelected);Add("刪除",DeleteSelected);StyleContextMenu(menu);FileList.ContextMenu=menu;}
    void FileList_ScrollChanged(object sender,ScrollChangedEventArgs e){if(e.VerticalChange<=0||e.VerticalOffset+e.ViewportHeight<e.ExtentHeight-160)return;int total;try{total=Directory.EnumerateFileSystemEntries(model.FolderPath).Take(fileVisibleLimit+FilePageSize+1).Count();}catch{return;}if(total<=fileVisibleLimit)return;fileVisibleLimit+=FilePageSize;RefreshFiles();}
    IEnumerable<FileRow> SelectedFiles()=>FileList.SelectedItems.Cast<FileRow>();
    void OpenSelected(){foreach(var f in SelectedFiles())Process.Start(new ProcessStartInfo(f.Path){UseShellExecute=true});}
    void RevealSelected(){var f=SelectedFiles().FirstOrDefault();if(f!=null)Process.Start(new ProcessStartInfo("explorer.exe",$"/select,\"{f.Path}\""){UseShellExecute=true});}
    void CopySelected(bool cut){var files=SelectedFiles().Select(x=>x.Path).ToArray();if(files.Length==0)return;var data=new DataObject();data.SetData(DataFormats.FileDrop,files);data.SetData("Preferred DropEffect",new MemoryStream(new byte[]{cut?(byte)2:(byte)5,0,0,0}));Clipboard.SetDataObject(data,true);}
    void PasteFiles(){try{if(!Clipboard.ContainsFileDropList())return;var move=ClipboardPreferredDropEffect()==DragDropEffects.Move;foreach(var src in Clipboard.GetFileDropList().Cast<string>().Where(x=>!string.IsNullOrWhiteSpace(x))){var name=Path.GetFileName(src.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar));if(string.IsNullOrWhiteSpace(name))continue;var dst=UniquePath(Path.Combine(model.FolderPath,name));if(move)MoveFileOrDirectory(src,dst);else if(File.Exists(src))File.Copy(src,dst);else if(Directory.Exists(src))CopyDirectory(src,dst);}RefreshFiles();}catch(Exception ex){BeeXDialog.Alert(this,Localization.T("粘貼失敗",service.State.Language),ex.Message,service.State);}}
    static DragDropEffects ClipboardPreferredDropEffect(){try{var data=Clipboard.GetData("Preferred DropEffect");if(data is MemoryStream stream&&stream.Length>0)return (DragDropEffects)stream.ToArray()[0];if(data is byte[] bytes&&bytes.Length>0)return (DragDropEffects)bytes[0];}catch{}return DragDropEffects.Copy;}
    void RenameSelected(){var f=SelectedFiles().FirstOrDefault();if(f==null)return;var d=new Window{Title=Localization.T("重新命名",service.State.Language),Width=420,Height=170,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner};var p=new StackPanel{Margin=new Thickness(18)};var box=new TextBox{Text=f.Name,MinHeight=InputHeight(model.FontSize),Padding=InputPadding(model.FontSize)};var ok=new Button{Content=Localization.T("確定",service.State.Language),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};ok.Click+=(_,_)=>{try{var name=box.Text.Trim();if(string.IsNullOrWhiteSpace(name)||name.IndexOfAny(Path.GetInvalidFileNameChars())>=0)throw new IOException(Localization.T("文件名無效。",service.State.Language));var dst=Path.Combine(Path.GetDirectoryName(f.Path)!,name);if(File.Exists(dst)||Directory.Exists(dst))throw new IOException(Localization.T("目標名稱已存在。",service.State.Language));if(File.Exists(f.Path))File.Move(f.Path,dst);else Directory.Move(f.Path,dst);d.Close();RefreshFiles();}catch(Exception ex){BeeXDialog.Alert(d,Localization.T("重新命名失敗",service.State.Language),ex.Message,service.State);}};box.KeyDown+=(_,e)=>{if(e.Key==Key.Enter){ok.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));e.Handled=true;}};p.Children.Add(box);p.Children.Add(ok);d.Content=p;d.ShowDialog();}
    void DeleteSelected(){var selected=SelectedFiles().ToList();if(selected.Count==0||!BeeXDialog.Confirm(this,Localization.T("刪除項目",service.State.Language),Localization.Format("確定將選中的 {0} 個項目移到資源回收筒？",service.State.Language,selected.Count),service.State))return;foreach(var f in selected){try{if(File.Exists(f.Path))Microsoft.VisualBasic.FileIO.FileSystem.DeleteFile(f.Path,Microsoft.VisualBasic.FileIO.UIOption.OnlyErrorDialogs,Microsoft.VisualBasic.FileIO.RecycleOption.SendToRecycleBin);else if(Directory.Exists(f.Path))Microsoft.VisualBasic.FileIO.FileSystem.DeleteDirectory(f.Path,Microsoft.VisualBasic.FileIO.UIOption.OnlyErrorDialogs,Microsoft.VisualBasic.FileIO.RecycleOption.SendToRecycleBin);}catch{}}RefreshFiles();}
