    void Window_Drop(object s,DragEventArgs e){if(model.Kind!=NestKind.ManagedFiles||!e.Data.GetDataPresent(DataFormats.FileDrop))return;var failed=new List<string>();foreach(var src in (string[])e.Data.GetData(DataFormats.FileDrop)){try{var name=Path.GetFileName(src.TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar));if(string.IsNullOrWhiteSpace(name))continue;var dst=UniquePath(Path.Combine(model.FolderPath,name));MoveFileOrDirectory(src,dst);}catch(Exception ex){failed.Add($"{Path.GetFileName(src)}: {ex.Message}");}}RefreshFiles();if(failed.Count>0)BeeXDialog.Alert(this,"收納失敗",string.Join(Environment.NewLine,failed.Take(5)),service.State);}
    static string UniquePath(string p){if(!File.Exists(p)&&!Directory.Exists(p))return p;return Path.Combine(Path.GetDirectoryName(p)!,Path.GetFileNameWithoutExtension(p)+"_"+DateTime.Now.ToString("HHmmss")+Path.GetExtension(p));}
    static void CopyDirectory(string src,string dst){Directory.CreateDirectory(dst);foreach(var f in Directory.GetFiles(src))File.Copy(f,Path.Combine(dst,Path.GetFileName(f)));foreach(var d in Directory.GetDirectories(src))CopyDirectory(d,Path.Combine(dst,Path.GetFileName(d)));}
    static void MoveFileOrDirectory(string src,string dst)
    {
        if(File.Exists(src)){File.Move(src,dst);return;}
        if(!Directory.Exists(src))return;
        try{Directory.Move(src,dst);}
        catch(IOException){CopyDirectory(src,dst);Directory.Delete(src,true);}
    }
