    static BitmapSource? LoadImage(string path,int decodePixelWidth=0){if(string.IsNullOrWhiteSpace(path)||!File.Exists(path))return null;try{using var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite);var decoder=BitmapDecoder.Create(stream,BitmapCreateOptions.PreservePixelFormat|BitmapCreateOptions.IgnoreColorProfile,BitmapCacheOption.OnLoad);if(decoder.Frames.Count==0)return null;BitmapSource source=decoder.Frames[0];if(decodePixelWidth>0&&source.PixelWidth>decodePixelWidth){var scale=decodePixelWidth/(double)source.PixelWidth;source=new TransformedBitmap(source,new ScaleTransform(scale,scale));}source.Freeze();return source;}catch{try{using var image=System.Drawing.Image.FromFile(path);using var bitmap=new System.Drawing.Bitmap(image);var handle=bitmap.GetHbitmap();try{var width=decodePixelWidth>0?Math.Min(decodePixelWidth,bitmap.Width):bitmap.Width;var height=(int)Math.Round(bitmap.Height*(width/(double)bitmap.Width));var source=System.Windows.Interop.Imaging.CreateBitmapSourceFromHBitmap(handle,IntPtr.Zero,Int32Rect.Empty,BitmapSizeOptions.FromWidthAndHeight(width,height));source.Freeze();return source;}finally{DeleteObject(handle);}}catch{return null;}}}
