    static bool IsSessionPlaying(GlobalSystemMediaTransportControlsSession? session){try{return session?.GetPlaybackInfo().PlaybackStatus==GlobalSystemMediaTransportControlsSessionPlaybackStatus.Playing;}catch{return false;}}
    async Task<bool> TrySetPlaybackAsync(GlobalSystemMediaTransportControlsSession? session,bool targetPlaying)
    {
        bool ok=false;
        try{if(session!=null)ok=targetPlaying?await session.TryPlayAsync():await session.TryPauseAsync();}catch{ok=false;}
        await Task.Delay(160);
        var actual=IsSessionPlaying(session);
        if(actual==targetPlaying){optimisticPlaying=null;SetPlayPauseVisual(actual);return true;}
        Media(0xB3);
        await Task.Delay(220);
        actual=IsSessionPlaying(session);
        optimisticPlaying=null;
        SetPlayPauseVisual(actual);
        return actual==targetPlaying||ok;
    }
    void StartClock(){void Update(){var lang=service.State.Language;var culture=lang=="zh-CN"?new System.Globalization.CultureInfo("zh-CN"):lang=="en-US"?new System.Globalization.CultureInfo("en-US"):new System.Globalization.CultureInfo("zh-TW");ClockTime.Text=DateTime.Now.ToString("HH:mm:ss");ClockDate.Text=DateTime.Now.ToString(lang=="en-US"?"ddd, MMM d, yyyy":"yyyy/MM/dd dddd",culture);RenderClockCalendar();var alarms=service.State.Nests.SelectMany(x=>x.Todos).Where(x=>!x.Done&&x.DueAt>DateTime.Now).OrderBy(x=>x.DueAt).Take(3).Select(x=>$"{x.DueAt:MM/dd HH:mm}  {x.Text}").ToList();AlarmList.ItemsSource=alarms;AlarmHeader.Visibility=AlarmList.Visibility=alarms.Count>0?Visibility.Visible:Visibility.Collapsed;UpdateCollapsedWidgetHeader();}clockTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};clockTimer.Tick+=(_,_)=>Update();Update();clockTimer.Start();}
    void RenderClockCalendar(){if(model.Kind!=NestKind.Clock||ClockCalendar.Visibility!=Visibility.Visible)return;ClockCalendar.Children.Clear();ClockCalendar.RowDefinitions.Clear();ClockCalendar.ColumnDefinitions.Clear();for(var i=0;i<7;i++)ClockCalendar.ColumnDefinitions.Add(new ColumnDefinition());for(var i=0;i<7;i++)ClockCalendar.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});var now=DateTime.Today;var first=new DateTime(now.Year,now.Month,1);var startOffset=(int)first.DayOfWeek;var dayCount=DateTime.DaysInMonth(now.Year,now.Month);var textBrush=Foreground;var weekendBrush=new SolidColorBrush(Color.FromArgb(model.Skin=="Dark"?(byte)50:(byte)118,255,138,0));var workdayBrush=new SolidColorBrush(Color.FromArgb(model.Skin=="Dark"?(byte)32:(byte)72,255,255,255));var todayBrush=new SolidColorBrush(Color.FromRgb(255,138,0));string[] heads=["日","一","二","三","四","五","六"];for(var c=0;c<7;c++){var h=new TextBlock{Text=heads[c],HorizontalAlignment=HorizontalAlignment.Center,FontSize=10,FontWeight=FontWeights.SemiBold,Foreground=c is 0 or 6?new SolidColorBrush(Color.FromRgb(255,138,0)):textBrush,Margin=new Thickness(0,0,0,3)};Grid.SetColumn(h,c);ClockCalendar.Children.Add(h);}for(var day=1;day<=dayCount;day++){var index=startOffset+day-1;var row=index/7+1;var col=index%7;var isToday=day==now.Day;var cell=new Border{CornerRadius=new CornerRadius(8),Background=isToday?todayBrush:(col is 0 or 6?weekendBrush:workdayBrush),Margin=new Thickness(2),Padding=new Thickness(0,4,0,4),Child=new TextBlock{Text=day.ToString(),HorizontalAlignment=HorizontalAlignment.Center,TextAlignment=TextAlignment.Center,FontSize=11,FontWeight=isToday?FontWeights.SemiBold:FontWeights.Normal,Foreground=isToday?Brushes.White:textBrush}};Grid.SetRow(cell,row);Grid.SetColumn(cell,col);ClockCalendar.Children.Add(cell);}}
