    void BuildMusicLauncher(){if(HeaderBorder.Child is not Grid grid)return;var actions=grid.Children.OfType<StackPanel>().FirstOrDefault(x=>Grid.GetColumn(x)==2);if(actions==null)return;musicSourceButton=new Button{Content="♫",ToolTip=L("播放器 / 歌詞快取"),Padding=new Thickness(9,5,9,5),Tag="musicSource"};musicSourceButton.Click+=async(_,_)=>{await RefreshMusicAppsAsync();ShowMusicSourceMenu(false);};actions.Children.Insert(0,musicSourceButton);_ = RefreshMusicAppsAsync();ApplyMusicDisplayMode();}
    void ShowMusicSourceMenu(bool autoPrompt)
    {
        if(musicSourceButton==null)return;
        var menu=new ContextMenu();
        var sessions=mediaManager?.GetSessions().ToList()??[];
        if(sessions.Count>0)
        {
            menu.Items.Add(new MenuItem{Header=L("目前播放器"),IsEnabled=false});
            foreach(var session in sessions.OrderByDescending(IsPlayingSession))
            {
                var source=session.SourceAppUserModelId;
                var item=new MenuItem{Header=$"{FriendlyMediaAppName(source)}{(IsPlayingSession(session)?" · "+L("正在播放"):"")}",IsCheckable=true,IsChecked=preferredMediaSessionId==source};
                item.Click+=async(_,_)=>{preferredMediaSessionId=source;multiMediaPrompted=false;await RefreshMediaAsync();};
                menu.Items.Add(item);
            }
            menu.Items.Add(new Separator());
        }
        foreach(var app in detectedMusicApps)
        {
            var item=new MenuItem{Header=$"{L("開啟")} {app.Name}"};
            item.Click+=(_,_)=>OpenMusicApp(app);
            menu.Items.Add(item);
        }
        menu.Items.Add(new Separator());
        var auto=new MenuItem{Header=L("自動跟隨正在播放"),IsCheckable=true,IsChecked=string.IsNullOrWhiteSpace(preferredMediaSessionId)};
        auto.Click+=async(_,_)=>{preferredMediaSessionId="";multiMediaPrompted=false;await RefreshMediaAsync();};
        menu.Items.Add(auto);
        var scan=new MenuItem{Header=L("重新掃描音樂軟件")};
        scan.Click+=async(_,_)=>await RefreshMusicAppsAsync();
        menu.Items.Add(scan);
        var openLyrics=new MenuItem{Header=L("開啟歌詞快取資料夾")};
        openLyrics.Click+=(_,_)=>{Directory.CreateDirectory(MusicLyricsService.CacheDirectory);Process.Start(new ProcessStartInfo("explorer.exe",$"\"{MusicLyricsService.CacheDirectory}\""){UseShellExecute=true});};
        menu.Items.Add(openLyrics);
        var rematchLyrics=new MenuItem{Header=L("重新匹配歌詞")};
        rematchLyrics.Click+=async(_,_)=>await RematchLyricsAsync(clearCache:false);
        menu.Items.Add(rematchLyrics);
        var clearLyrics=new MenuItem{Header=L("清除此歌詞快取")};
        clearLyrics.Click+=async(_,_)=>await RematchLyricsAsync(clearCache:true);
        menu.Items.Add(clearLyrics);
        var offsetMenu=new MenuItem{Header=$"{L("歌詞偏移")}  {model.MusicLyricsOffsetSeconds:+0.0;-0.0;0.0}s"};
        foreach(var delta in new[]{-5d,-1d,1d,5d})
        {
            var item=new MenuItem{Header=$"{(delta>0?"+":"")}{delta:0}s"};
            item.Click+=(_,_)=>{model.MusicLyricsOffsetSeconds=Math.Clamp(model.MusicLyricsOffsetSeconds+delta,-30,30);service.Save();UpdateLyricLine(inferredPlaybackPosition);};
            offsetMenu.Items.Add(item);
        }
        var resetOffset=new MenuItem{Header=L("清除")};
        resetOffset.Click+=(_,_)=>{model.MusicLyricsOffsetSeconds=0;service.Save();UpdateLyricLine(inferredPlaybackPosition);};
        offsetMenu.Items.Add(new Separator());
        offsetMenu.Items.Add(resetOffset);
        menu.Items.Add(offsetMenu);
        StyleContextMenu(menu);
        menu.PlacementTarget=musicSourceButton;
        menu.IsOpen=true;
        if(autoPrompt)menu.Closed+=(_,_)=>multiMediaPrompted=false;
    }
    async Task RematchLyricsAsync(bool clearCache)
    {
        var title=musicTitle.Text?.Trim()??"";
        var artist=musicArtist.Text?.Trim()??"";
        if(string.IsNullOrWhiteSpace(title)||title==L("尚無播放中的媒體"))return;
        if(clearCache)MusicLyricsService.ClearCache(title,artist);
        currentLyrics=[];
        lastLyricIndex=-1;
        lyricPrevious.Text="";
        lyricCurrent.Text=L("正在尋找歌詞…");
        lyricNext.Text="";
        var key=currentMediaKey;
        // skipCache=true：跳过缓存重新搜索（但不清除缓存文件），新结果覆盖旧缓存
        await LoadLyricsAsync(title,artist,key,lastKnownMediaDuration,skipCache:true);
    }
