    static BitmapSource? BitmapFromHBitmapWithAlpha(IntPtr hbm){try{if(GetGdiObject(hbm,Marshal.SizeOf<GdiBitmap>(),out var bm)==0||bm.bmWidth<=0||bm.bmHeight==0)return null;var w=bm.bmWidth;var h=Math.Abs(bm.bmHeight);var info=new GdiBitmapInfoHeader{biSize=Marshal.SizeOf<GdiBitmapInfoHeader>(),biWidth=w,biHeight=-h,biPlanes=1,biBitCount=32,biCompression=0};var pixels=new byte[w*h*4];var hdc=GetDC(IntPtr.Zero);try{if(GetDIBits(hdc,hbm,0,(uint)h,pixels,ref info,0)==0)return null;}finally{ReleaseDC(IntPtr.Zero,hdc);}var hasAlpha=false;for(var i=3;i<pixels.Length;i+=4)if(pixels[i]!=0){hasAlpha=true;break;}if(!hasAlpha)for(var i=3;i<pixels.Length;i+=4)pixels[i]=255;var bs=BitmapSource.Create(w,h,96,96,PixelFormats.Pbgra32,null,pixels,w*4);bs.Freeze();return bs;}catch{return null;}}
    static string PlayerKeyword(string id){var lower=id.ToLowerInvariant();return lower.Contains("cloudmusic")||lower.Contains("netease")?"cloudmusic":lower.Contains("qqmusic")||lower.Contains("tencent")?"qqmusic":lower.Contains("kugou")||lower.Contains("kgmusic")?"kugou":lower.Contains("spotify")?"spotify":lower.Contains("applemusic")||lower.Contains("apple.music")?"applemusic":lower.Contains("itunes")?"itunes":"";}
    string FindPlayerExePath(string id){if(string.IsNullOrWhiteSpace(id))return "";bool IsExe(string p)=>p.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)&&File.Exists(p);var keyword=PlayerKeyword(id);var apps=detectedMusicApps.Count>0?detectedMusicApps:FindMusicApps();if(keyword.Length>0){var hit=apps.FirstOrDefault(x=>IsExe(x.Path)&&x.Path.ToLowerInvariant().Contains(keyword));if(hit!=null)return hit.Path;}try{var frag=id.Split('!','_','.',' ').FirstOrDefault(x=>x.Length>=4)?.ToLowerInvariant()??"";if(frag.Length>0)foreach(var p in Process.GetProcesses()){try{if(p.ProcessName.ToLowerInvariant().Contains(frag)){var f=p.MainModule?.FileName;if(!string.IsNullOrWhiteSpace(f)&&IsExe(f))return f;}}catch{}}}catch{}return "";}
    void TickCollapsedMusicMarquee()
    {
        if(collapsedMusicLyric==null||collapsedMusicLyricClip==null||collapsedMusicLyricTransform==null||!model.IsCollapsed){StopCollapsedMusicMarquee();return;}
        collapsedMusicLyric.Measure(new System.Windows.Size(double.PositiveInfinity,double.PositiveInfinity));
        var overflow=collapsedMusicLyric.DesiredSize.Width-collapsedMusicLyricClip.ActualWidth;
        if(overflow<=0){collapsedMusicLyricTransform.X=0;return;}
        // 進度來源：有時間軸用播放位置在當前句內的進度；無時間軸按顯示後經過的壁鐘時間（8 秒推完）
        double progress;
        if(currentLyrics.Count>0&&lastLyricIndex>=0&&lastLyricIndex<currentLyrics.Count)
        {
            var start=currentLyrics[lastLyricIndex].Time;
            var end=lastLyricIndex+1<currentLyrics.Count?currentLyrics[lastLyricIndex+1].Time:start+TimeSpan.FromSeconds(10);
            var span=Math.Max(1,(end-start).TotalSeconds);
            progress=Math.Clamp((inferredPlaybackPosition-start).TotalSeconds/span,0,1);
        }
        else progress=Math.Clamp((DateTime.UtcNow-collapsedMusicLineDisplayUtc).TotalSeconds/8,0,1);
        // 句首 18% 完整停留、句尾 12% 提前推到盡頭，中間線性推進；再用指數插值抹平 250ms 輪詢的階梯感
        var t=Math.Clamp((progress-.18)/.7,0,1);
        var targetX=-overflow*t;
        collapsedMusicLyricTransform.X+=(targetX-collapsedMusicLyricTransform.X)*.12;
    }
