    void ResetMusicArtwork(){if(model.Kind!=NestKind.Music)return;ApplySkin();musicInfoCard.Background=new SolidColorBrush(Color.FromArgb(132,5,9,16));musicLyricsCard.Background=new SolidColorBrush(Color.FromArgb(132,5,9,16));musicProgressCard.Background=new SolidColorBrush(Color.FromArgb(104,5,9,16));musicCover.Visibility=Visibility.Collapsed;if(MusicPanel.Children.Count>0&&MusicPanel.Children[0] is StackPanel rstack){foreach(var grid in rstack.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>())foreach(var b in grid.Children.OfType<Button>()){b.Background=new SolidColorBrush(Color.FromArgb(116,5,9,16));b.Foreground=Brushes.White;}var rg=rstack.Children.OfType<System.Windows.Controls.Primitives.UniformGrid>().ToList();if(rg.Count>0&&rg[0].Children.Count>1&&rg[0].Children[1] is Button rplay)rplay.Background=new SolidColorBrush(Color.FromArgb(235,255,138,0));}ApplyMusicCustomColors();}
    async Task LoadLyricsAsync(string title,string artist,string key,TimeSpan duration,bool skipCache=false){lastLyricsAttemptUtc=DateTime.UtcNow;lyricsLoadCancellation?.Cancel();lyricsLoadCancellation?.Dispose();lyricsLoadCancellation=new CancellationTokenSource();try{var appFolders=detectedMusicApps.Select(x=>string.IsNullOrWhiteSpace(x.Path)?null:Path.GetDirectoryName(x.Path)).Where(x=>!string.IsNullOrWhiteSpace(x)).Cast<string>();var document=await MusicLyricsService.FindAsync(title,artist,appFolders,duration,lyricsLoadCancellation.Token,skipCache:skipCache);if(key!=currentMediaKey)return;if(document==null){currentLyrics=[];lyricPrevious.Text="";lyricCurrent.Text=L("暫時找不到歌詞");lyricNext.Text="";lyricStatus.Text="";// 即使没找到也启动 watcher，等待播放器落盘歌词后实时加载
StartLyricsWatcher(title,artist,key,duration);return;}currentLyrics=document.Lines;lyricStatus.Text="";var correctedDuration=NormalizeMediaDuration(lastKnownMediaDuration);if(correctedDuration>TimeSpan.FromSeconds(10))UpdateMusicProgress(inferredPlaybackPosition,correctedDuration);UpdateLyricLine(inferredPlaybackPosition);// 启动 watcher 监听本地歌词文件变化（覆盖在线 API 命中后播放器后续落盘的场景）
StartLyricsWatcher(title,artist,key,duration);}catch(OperationCanceledException){}catch{if(key==currentMediaKey){currentLyrics=[];lyricCurrent.Text=L("歌詞載入失敗");lyricStatus.Text="";StartLyricsWatcher(title,artist,key,duration);}}}

    void StartLyricsWatcher(string title,string artist,string key,TimeSpan duration)
    {
        if(key!=currentMediaKey)return;
        currentLyricsTitle=title;currentLyricsArtist=artist;lastKnownMediaDurationForWatch=duration;
        lyricsWatcher??=new MusicLyricsWatcher(Dispatcher);
        lyricsWatcher.Start(title,artist,file=>OnWatchedLyricsFile(file,key));
    }

    async void OnWatchedLyricsFile(string file,string key)
    {
        if(key!=currentMediaKey||string.IsNullOrEmpty(currentLyricsTitle))return;
        try
        {
            var document=await Task.Run(()=>MusicLyricsService.TryLoadFromLocalFile(file,currentLyricsTitle,currentLyricsArtist,expectedDuration:lastKnownMediaDurationForWatch));
            if(document==null||key!=currentMediaKey)return;
            currentLyrics=document.Lines;lyricStatus.Text="";
            UpdateLyricLine(inferredPlaybackPosition);
        }
        catch{}
    }
    void UpdateLyricLine(TimeSpan position){if(currentLyrics.Count==0)return;position+=TimeSpan.FromSeconds(model.MusicLyricsOffsetSeconds);if(position<TimeSpan.Zero)position=TimeSpan.Zero;var low=0;var high=currentLyrics.Count-1;while(low<=high){var mid=(low+high)/2;if(currentLyrics[mid].Time<=position)low=mid+1;else high=mid-1;}var index=Math.Clamp(high,0,currentLyrics.Count-1);var context=LyricContextLineCount();if(index==lastLyricIndex&&lyricPrevious.Visibility==(context>0?Visibility.Visible:Visibility.Collapsed))return;lastLyricIndex=index;lyricCurrent.Text=currentLyrics[index].Text;lyricPrevious.Text=context<=0?"":string.Join("\n",Enumerable.Range(Math.Max(0,index-context),index-Math.Max(0,index-context)).Select(i=>currentLyrics[i].Text));lyricNext.Text=context<=0?"":string.Join("\n",Enumerable.Range(index+1,Math.Max(0,Math.Min(currentLyrics.Count,index+1+context)-(index+1))).Select(i=>currentLyrics[i].Text));lyricPrevious.Visibility=lyricNext.Visibility=context>0?Visibility.Visible:Visibility.Collapsed;}
    int LyricContextLineCount(){if(ActualHeight>=430)return 3;if(ActualHeight>=350)return 2;if(ActualHeight>=260)return 1;return 0;}
    static TimeSpan GetTimelineDuration(TimeSpan start,TimeSpan end){if(end<=TimeSpan.Zero)return TimeSpan.Zero;var span=end>start?end-start:TimeSpan.Zero;if(start>TimeSpan.Zero&&span>TimeSpan.FromSeconds(10)&&span<=TotalReasonableDuration())return span;if(end<=TotalReasonableDuration())return end;return span>TimeSpan.FromSeconds(10)&&span<=TotalReasonableDuration()?span:TimeSpan.Zero;}
    static TimeSpan GetTimelinePosition(TimeSpan position,TimeSpan start,TimeSpan duration){var absolute=position<TimeSpan.Zero?TimeSpan.Zero:position;var relative=position>=start?position-start:position;if(relative<TimeSpan.Zero)relative=TimeSpan.Zero;if(duration>TimeSpan.Zero&&absolute<=duration&&absolute>relative+TimeSpan.FromSeconds(2))return absolute;if(duration>TimeSpan.Zero&&relative>duration)relative=duration;return relative;}
    TimeSpan NormalizeMediaDuration(TimeSpan raw){var lyricDuration=currentLyrics.Count>0?currentLyrics[^1].Time+TimeSpan.FromSeconds(8):TimeSpan.Zero;if(raw<TimeSpan.FromSeconds(25)||raw>TotalReasonableDuration())raw=TimeSpan.Zero;if(raw>TimeSpan.Zero){if(lastKnownMediaDuration<=TimeSpan.FromSeconds(10)||Math.Abs((raw-lastKnownMediaDuration).TotalSeconds)<=Math.Max(5,lastKnownMediaDuration.TotalSeconds*.18)){lastKnownMediaDuration=raw;pendingMediaDuration=TimeSpan.Zero;pendingMediaDurationHits=0;}else if(lastKnownMediaDuration>TimeSpan.FromSeconds(10)&&Math.Abs((raw-lastKnownMediaDuration).TotalSeconds)>lastKnownMediaDuration.TotalSeconds*.5){// 切歌：新时长与旧时长差异超过 50%，直接接受新值，不走防抖
lastKnownMediaDuration=raw;pendingMediaDuration=TimeSpan.Zero;pendingMediaDurationHits=0;}else{if(Math.Abs((raw-pendingMediaDuration).TotalSeconds)<=2)pendingMediaDurationHits++;else{pendingMediaDuration=raw;pendingMediaDurationHits=1;}if(pendingMediaDurationHits>=2){lastKnownMediaDuration=raw;pendingMediaDuration=TimeSpan.Zero;pendingMediaDurationHits=0;}}}var best=lastKnownMediaDuration>TimeSpan.FromSeconds(10)?lastKnownMediaDuration:lyricDuration>TimeSpan.FromSeconds(20)?lyricDuration:TimeSpan.Zero;if(lyricDuration>TimeSpan.FromSeconds(40)&&best>TimeSpan.FromSeconds(40)&&Math.Abs((lyricDuration-best).TotalSeconds)<=35)best=lyricDuration>best?lyricDuration:best;if(best>TimeSpan.FromSeconds(10))lastKnownMediaDuration=best;return best;}
    static TimeSpan TotalReasonableDuration()=>TimeSpan.FromHours(6);
    TimeSpan GetEstimatedPlaybackPosition(bool playing,TimeSpan reported,DateTimeOffset lastUpdated,TimeSpan duration,double? playbackRate,bool forceExternal=false)
    {
        if(userSeekingProgress)return TimeSpan.FromSeconds(musicProgress.Value);
        // seek 被播放器拒绝（IsPlaybackPositionEnabled=false）：强制使用 SMTC 真实位置
        if(seekDenied){seekDenied=false;seekActive=false;inferredPlaybackPosition=reported;playbackAnchorInitialized=true;lastPlaybackPollUtc=DateTime.UtcNow;lastTimelinePosition=lastReportedPlaybackPosition=reported;lastTimelineUpdatedTime=lastUpdated;return reported;}
        var nowUtc=DateTime.UtcNow;
        var now=DateTimeOffset.Now;
        var rate=playbackRate??1.0;if(rate<=0)rate=1.0;
        // SMTC 的 Position 是「LastUpdatedTime 时刻」的快照；真实位置 = 快照位置 + 距该时刻的真实經過時間。
        // 播放器每次推送新快照（Position 或 LastUpdatedTime 变化）都会自动重新锚定，因此不会因网络/缓冲而累积漂移。
        var hasSnapshotTime=lastUpdated>DateTimeOffset.MinValue.AddYears(1)&&lastUpdated<=now.AddSeconds(3);
        var snapshotChanged=Math.Abs((reported-lastTimelinePosition).TotalSeconds)>0.4||lastUpdated!=lastTimelineUpdatedTime;
        TimeSpan position;
        if(playing)
        {
            var real=hasSnapshotTime?reported+TimeSpan.FromTicks((long)(Math.Max(0,(now-lastUpdated).Ticks)*rate)):reported;
            if(seekActive&&playbackAnchorInitialized)
            {
                // seek 后等播放器快照追上目标；期间以本地时钟平滑前进，快照追近（<10s）后恢复以真实位置为准
                var d=nowUtc-lastPlaybackPollUtc;position=d>TimeSpan.Zero&&d<TimeSpan.FromSeconds(2)?inferredPlaybackPosition+TimeSpan.FromTicks((long)(d.Ticks*rate)):inferredPlaybackPosition;
                if(snapshotChanged&&Math.Abs((real-inferredPlaybackPosition).TotalSeconds)<10){seekActive=false;position=real;}
            }
            else if(hasSnapshotTime)position=real; // 以播放器快照为准，随每次快照推送自动重对齐
            else if(playbackAnchorInitialized)
            {
                // 播放器未提供有效快照时间戳：本地时钟自增，reported 变化时立即重对齐
                if(snapshotChanged)position=reported;
                else{var d=nowUtc-lastPlaybackPollUtc;position=d>TimeSpan.Zero&&d<TimeSpan.FromSeconds(2)?inferredPlaybackPosition+TimeSpan.FromTicks((long)(d.Ticks*rate)):inferredPlaybackPosition;}
            }
            else position=reported;
        }
        else position=(reported<=TimeSpan.FromSeconds(1)&&inferredPlaybackPosition>TimeSpan.FromSeconds(1))?inferredPlaybackPosition:reported;
        if(position<TimeSpan.Zero)position=TimeSpan.Zero;
        if(duration>TimeSpan.Zero&&position>duration)position=duration;
        // 单调性保护：播放时不小幅倒退；换曲的大幅回退由媒体 key 变更重置 inferred，不在此误判
        if(playing&&!seekActive&&playbackAnchorInitialized&&position<inferredPlaybackPosition&&(inferredPlaybackPosition-position)<TimeSpan.FromSeconds(2))position=inferredPlaybackPosition;
        lastTimelinePosition=reported;lastReportedPlaybackPosition=reported;lastTimelineUpdatedTime=lastUpdated;lastPlaybackPollUtc=nowUtc;
        inferredPlaybackPosition=position;
        playbackAnchorInitialized=playing;
        return position;
    }
    void SetPlayPauseVisual(bool playing){PlayPauseButton.Content=new WpfImage{Source=SvgIcon.Load(playing?"player-pause":"player-play",20,System.Windows.Media.Brushes.White),Width=20,Height=20};PlayPauseButton.ToolTip=playing?L("暫停"):L("播放");}
    void UpdateMusicProgress(TimeSpan position,TimeSpan duration){if(userSeekingProgress)return;updatingMusicProgress=true;musicProgress.Maximum=Math.Max(1,duration.TotalSeconds);musicProgress.Value=Math.Clamp(position.TotalSeconds,0,musicProgress.Maximum);musicElapsed.Text=FormatMediaTime(position);musicDuration.Text=duration>TimeSpan.Zero?FormatMediaTime(duration-position):"--:--";updatingMusicProgress=false;}
    void MusicProgress_Jump(object sender,MouseButtonEventArgs e){if(updatingMusicProgress)return;userSeekingProgress=true;musicProgress.CaptureMouse();SetMusicProgressFromPoint(e.GetPosition(musicProgress).X);e.Handled=true;}
    void MusicProgress_Drag(object sender,System.Windows.Input.MouseEventArgs e){if(!userSeekingProgress||e.LeftButton!=MouseButtonState.Pressed)return;SetMusicProgressFromPoint(e.GetPosition(musicProgress).X);e.Handled=true;}
    async void MusicProgress_Commit(object sender,MouseButtonEventArgs e){if(!userSeekingProgress)return;SetMusicProgressFromPoint(e.GetPosition(musicProgress).X);userSeekingProgress=false;if(musicProgress.IsMouseCaptured)musicProgress.ReleaseMouseCapture();e.Handled=true;await CommitMusicSeekAsync();}
        async void MusicProgress_LostCapture(object sender,System.Windows.Input.MouseEventArgs e){if(!userSeekingProgress)return;userSeekingProgress=false;await CommitMusicSeekAsync();}
    void SetMusicProgressFromPoint(double x){var width=Math.Max(1,musicProgress.ActualWidth);var ratio=Math.Clamp(x/width,0,1);musicProgress.Value=ratio*Math.Max(1,musicProgress.Maximum);var target=TimeSpan.FromSeconds(musicProgress.Value);musicElapsed.Text=FormatMediaTime(target);var dur=TimeSpan.FromSeconds(musicProgress.Maximum);musicDuration.Text=dur>TimeSpan.Zero?FormatMediaTime(dur-target):"--:--";UpdateLyricLine(target);QueueLiveMusicSeek(target);}
    void QueueLiveMusicSeek(TimeSpan target){if(!userSeekingProgress||liveSeekBusy)return;var now=DateTime.UtcNow;if(now-lastLiveSeekUtc<TimeSpan.FromMilliseconds(260)&&Math.Abs((target-lastLiveSeekTarget).TotalSeconds)<1.2)return;lastLiveSeekUtc=now;lastLiveSeekTarget=target;_ = LiveSeekMusicAsync(target);}
    async Task LiveSeekMusicAsync(TimeSpan target){liveSeekBusy=true;try{var session=ResolveMediaSession();if(session==null)return;await TrySeekMediaAsync(session,target,ok=>{if(!ok)seekDenied=true;});}catch{}finally{liveSeekBusy=false;}}
    void AcceptMusicSeek(TimeSpan target,bool render){inferredPlaybackPosition=lastReportedPlaybackPosition=target;lastTimelineUpdatedTime=DateTimeOffset.MinValue;lastPlaybackPollUtc=DateTime.UtcNow;playbackAnchorInitialized=true;seekActive=true;UpdateLyricLine(target);if(render)UpdateMusicProgress(target,NormalizeMediaDuration(lastKnownMediaDuration));}
    async Task CommitMusicSeekAsync(){try{var session=ResolveMediaSession();if(session==null)return;var target=TimeSpan.FromSeconds(musicProgress.Value);bool denied=false;var ok=await TrySeekMediaAsync(session,target,r=>denied=!r);if(denied){seekDenied=true;seekActive=false;// 播放器不支持跳转，闪回真实位置
var flash=musicElapsed.Foreground;musicElapsed.Foreground=Brushes.Gray;musicDuration.Foreground=Brushes.Gray;await Task.Delay(900);musicElapsed.Foreground=flash;musicDuration.Foreground=flash;}
else AcceptMusicSeek(target,!denied);await Task.Delay(80);await RefreshMediaAsync(forceExternal:false);}catch{}}
    static async Task<bool> TrySeekMediaAsync(GlobalSystemMediaTransportControlsSession session,TimeSpan target,Action<bool>? onResult=null){try{var controls=session.GetPlaybackInfo().Controls;if(!controls.IsPlaybackPositionEnabled){onResult?.Invoke(false);return false;}var timeline=session.GetTimelineProperties();var min=timeline.MinSeekTime;var max=timeline.MaxSeekTime;if(max<=min){min=timeline.StartTime;max=timeline.EndTime;}target=target<min?min:target;if(max>min&&target>max)target=max;var ok=await session.TryChangePlaybackPositionAsync(target.Ticks);if(ok){await Task.Delay(100);var after=session.GetTimelineProperties();var afterDuration=GetTimelineDuration(after.StartTime,after.EndTime);var relative=GetTimelinePosition(after.Position,after.StartTime,afterDuration);if(Math.Abs((relative-target).TotalSeconds)<3)ok=true;}onResult?.Invoke(ok);return ok;}catch{onResult?.Invoke(false);return false;}}
    static string FormatMediaTime(TimeSpan value)=>value.TotalHours>=1?$"{(int)value.TotalHours:00}:{value.Minutes:00}:{value.Seconds:00}":$"{(int)value.TotalMinutes:00}:{value.Seconds:00}";
