    async Task LoadWeatherAsync(bool geocode=false){var revision=++weatherRevision;var uiLang=service.State.Language;try{WeatherDetail.Text=Localization.T("正在更新…",uiLang);WeatherPanel.Background=Brushes.Transparent;if(geocode){var cityQuery=model.City.Trim();JsonElement results=default;JsonDocument? gd=null;foreach(var lang in new[]{"zh","en"}){gd?.Dispose();var geo=await WeatherHttp.GetStringAsync($"https://geocoding-api.open-meteo.com/v1/search?count=1&language={lang}&name="+Uri.EscapeDataString(cityQuery));if(revision!=weatherRevision)return;gd=JsonDocument.Parse(geo);if(gd.RootElement.TryGetProperty("results",out results)&&results.GetArrayLength()>0)break;}using(gd){if(results.ValueKind==JsonValueKind.Undefined||results.GetArrayLength()==0)throw new Exception(Localization.T("找不到城市",uiLang));var first=results[0];model.Latitude=first.GetProperty("latitude").GetDouble();model.Longitude=first.GetProperty("longitude").GetDouble();model.City=first.GetProperty("name").GetString()??model.City;WeatherCity.Text=model.City;}}var url=$"https://api.open-meteo.com/v1/forecast?latitude={model.Latitude}&longitude={model.Longitude}&current=temperature_2m,apparent_temperature,relative_humidity_2m,weather_code,wind_speed_10m,precipitation,pressure_msl&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,uv_index_max,sunrise,sunset&forecast_days=7&timezone=auto";var weatherJson=await WeatherHttp.GetStringAsync(url);if(revision!=weatherRevision)return;using var doc=JsonDocument.Parse(weatherJson);var c=doc.RootElement.GetProperty("current");var code=c.GetProperty("weather_code").GetInt32();WeatherIcon.Source=WeatherIconImage(code);WeatherTemp.Text=$"{c.GetProperty("temperature_2m").GetDouble():0}°";var apparent=c.GetProperty("apparent_temperature").GetDouble();var humidity=c.GetProperty("relative_humidity_2m").GetInt32();var wind=c.GetProperty("wind_speed_10m").GetDouble();weatherApparentText=$"{apparent:0}°";weatherHumidityText=$"{humidity}%";var precipitation=c.TryGetProperty("precipitation",out var precip)?precip.GetDouble():0;var pressure=c.TryGetProperty("pressure_msl",out var pmsl)?pmsl.GetDouble():0;weatherCurrentDetail=$"{Localization.T("今日",uiLang)} · {Localization.T("體感",uiLang)} {apparent:0}°  ·  {Localization.T("濕度",uiLang)} {humidity}%  ·  {Localization.T("風速",uiLang)} {wind:0} km/h";weatherForecastLines.Clear();weatherMetricLines.Clear();if(doc.RootElement.TryGetProperty("daily",out var daily)){var highs=daily.GetProperty("temperature_2m_max");var lows=daily.GetProperty("temperature_2m_min");var rains=daily.GetProperty("precipitation_probability_max");var codes=daily.GetProperty("weather_code");var uv=daily.TryGetProperty("uv_index_max",out var uvArray)?uvArray:default;var sunrise=daily.TryGetProperty("sunrise",out var riseArray)?riseArray:default;var sunset=daily.TryGetProperty("sunset",out var setArray)?setArray:default;var days=Math.Min(7,highs.GetArrayLength());for(var i=0;i<days;i++){var day=i==0?Localization.T("今日",uiLang):DateTime.Today.AddDays(i).ToString("MM/dd");var dayCode=codes[i].GetInt32();weatherForecastLines.Add($"{day}|{WeatherIconKey(dayCode)}|{lows[i].GetDouble():0}–{highs[i].GetDouble():0}°\n{Localization.T("雨",uiLang)} {rains[i].GetInt32()}%");}if(days>0){if(uv.ValueKind!=JsonValueKind.Undefined)weatherMetricLines.Add((Localization.T("紫外線",uiLang),$"{uv[0].GetDouble():0.0}"));if(sunrise.ValueKind!=JsonValueKind.Undefined)weatherMetricLines.Add((Localization.T("日出",uiLang),DateTime.Parse(sunrise[0].GetString()??DateTime.Now.ToString()).ToString("HH:mm")));if(sunset.ValueKind!=JsonValueKind.Undefined)weatherMetricLines.Add((Localization.T("日落",uiLang),DateTime.Parse(sunset[0].GetString()??DateTime.Now.ToString()).ToString("HH:mm")));}}weatherMetricLines.Add((Localization.T("降水",uiLang),$"{precipitation:0.0} mm"));if(pressure>0)weatherMetricLines.Add((Localization.T("氣壓",uiLang),$"{pressure:0} hPa"));if(revision!=weatherRevision)return;RenderWeatherDetail();service.Save();}catch