    static ImageSource WeatherIconImage(int code)=>WeatherIconImage(WeatherIconKey(code));
    static string WeatherIconKey(int c)=>c switch{0=>"sunny",1 or 2=>"partly",3=>"cloudy",45 or 48=>"fog",>=51 and <=67=>"rain",>=71 and <=77=>"snow",>=80 and <=82=>"shower",>=95=>"thunder",_=>"cloudy"};
    static ImageSource WeatherIconImage(string key)
    {
        var group=new DrawingGroup();
        using(var dc=group.Open())
        {
            var sun=new SolidColorBrush(Color.FromRgb(255,196,0));var sunEdge=new SolidColorBrush(Color.FromRgb(255,138,0));
            var cloud=new SolidColorBrush(Color.FromRgb(245,250,255));var cloudShade=new SolidColorBrush(Color.FromRgb(192,210,230));
            var blue=new SolidColorBrush(Color.FromRgb(46,144,250));var darkBlue=new SolidColorBrush(Color.FromRgb(22,84,160));
            var gray=new SolidColorBrush(Color.FromRgb(150,160,175));var snow=new SolidColorBrush(Color.FromRgb(132,212,255));
            void DrawSun(double x,double y,double r){dc.DrawEllipse(sun,null,new WpfPoint(x,y),r,r);dc.DrawEllipse(null,new WpfPen(sunEdge,2),new WpfPoint(x,y),r,r);for(var a=0;a<360;a+=45){var rad=a*Math.PI/180;dc.DrawLine(new WpfPen(sunEdge,4){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new WpfPoint(x+Math.Cos(rad)*(r+7),y+Math.Sin(rad)*(r+7)),new WpfPoint(x+Math.Cos(rad)*(r+17),y+Math.Sin(rad)*(r+17)));}}
            void DrawCloud(double ox,double oy,double scale=1){var pen=new WpfPen(cloudShade,2);dc.DrawEllipse(cloud,pen,new WpfPoint(ox+28*scale,oy+37*scale),18*scale,18*scale);dc.DrawEllipse(cloud,pen,new WpfPoint(ox+48*scale,oy+29*scale),24*scale,24*scale);dc.DrawEllipse(cloud,pen,new WpfPoint(ox+70*scale,oy+40*scale),20*scale,20*scale);dc.DrawRoundedRectangle(cloud,pen,new Rect(ox+16*scale,oy+38*scale,70*scale,28*scale),14*scale,14*scale);}
            void DrawRain(double ox,double oy){for(var i=0;i<3;i++){var x=ox+30+i*18;dc.DrawLine(new WpfPen(blue,5){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new WpfPoint(x,oy+73),new WpfPoint(x-8,oy+91));}}
            void DrawFog(){for(var y=70;y<=90;y+=10)dc.DrawLine(new WpfPen(gray,5){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new WpfPoint(18,y),new WpfPoint(82,y));}
            if(key=="sunny"){DrawSun(50,50,24);}
            else if(key=="partly"){DrawSun(34,33,17);DrawCloud(12,18);}
            else {DrawCloud(7,12);}
            if(key is "rain" or "shower")DrawRain(4,0);
            if(key=="thunder"){DrawRain(4,0);var bolt=Geometry.Parse("M50,66 L36,93 L55,83 L48,104 L72,74 L55,82 Z");dc.DrawGeometry(new SolidColorBrush(Color.FromRgb(255,202,40)),new WpfPen(sunEdge,1.5),bolt);}
            if(key=="snow"){foreach(var p in new[]{new WpfPoint(30,82),new WpfPoint(50,92),new WpfPoint(70,82)}){dc.DrawLine(new WpfPen(snow,3){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new WpfPoint(p.X-6,p.Y),new WpfPoint(p.X+6,p.Y));dc.DrawLine(new WpfPen(snow,3){StartLineCap=PenLineCap.Round,EndLineCap=PenLineCap.Round},new WpfPoint(p.X,p.Y-6),new WpfPoint(p.X,p.Y+6));}}
            if(key=="fog")DrawFog();
        }
        group.Freeze();
        var image=new DrawingImage(group);image.Freeze();return image;
    }
    void Screenshot_Click(object s,RoutedEventArgs e){var restore=model.IsVisible;Hide();service.CaptureScreen(()=>Dispatcher.BeginInvoke(new Action(()=>{if(restore&&!AllowClose){Show();Topmost=true;Activate();Topmost=model.Pinned;}}),DispatcherPriority.ApplicationIdle));}
    void OpenCaptures_Click(object s,RoutedEventArgs e)=>service.OpenCaptureFolder();
}


